WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, p.ViewCount, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.Score DESC NULLS FIRST) AS UserRank, SUM(v.BountyAmount) OVER (PARTITION BY p.Id) AS TotalBounty FROM Posts AS p LEFT JOIN Votes AS v ON p.Id = v.PostId AND v.VoteTypeId IN (9, 8) WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), TopPosts AS (SELECT rp.* FROM RankedPosts AS rp WHERE rp.UserRank <= 5), PostComments AS (SELECT c.PostId, COUNT(c.Id) AS CommentCount, GROUP_CONCAT(c.Text, ' | ') AS CommentTexts FROM Comments AS c GROUP BY c.PostId) SELECT tp.PostId, tp.Title, tp.CreationDate, tp.Score, tp.ViewCount, COALESCE(pc.CommentCount, 0) AS TotalComments, COALESCE(pc.CommentTexts, 'No comments') AS Comments, tp.TotalBounty FROM TopPosts AS tp LEFT JOIN PostComments AS pc ON tp.PostId = pc.PostId ORDER BY tp.Score DESC NULLS FIRST, tp.ViewCount DESC NULLS FIRST